  for(int h=1;h<=harmonics;++h){double angle=MathConstants<double>::twoPi*h/tableSize;float amplitude=harmonic(b,f,h);double sn=0,cs=1,ds=std::sin(angle),dc=std::cos(angle);for(int i=0;i<tableSize;++i){table[i]+=amplitude*(float)(b==4&&f>=4&&f<=6?cs:sn);double next=sn*dc+cs*ds;cs=cs*dc-sn*ds;sn=next;}}
