 for(auto* base:getParameters())if(auto* par=dynamic_cast<AudioProcessorParameterWithID*>(base))rawParameters.push_back(state.getRawParameterValue(par->paramID));
 for(int slot=0;slot<64;++slot){connectionEnabledIndices[slot]=state.getParameter(fxId(slot,"enabled"))->getParameterIndex();connectionWetIndices[slot]=state.getParameter(fxId(slot,"wet"))->getParameterIndex();}effectiveParameters.resize(rawParameters.size());liveModBaseValues.resize(rawParameters.size());for(int source=3;source<11;++source)liveSources[source].store(.5f);macroSmoothing.resize(rawParameters.size());for(int m=0;m<8;++m)macroIndices[m]=state.getParameter("macro"+String(m+1))->getParameterIndex();
